import time
from typing import List, Optional, TypedDict
from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper
from taf.rfrl.csv4all.resources.test_cases.netact_feature_test import NetactFeatureTest
from taf.rfrl.csv4all.resources.node.feature.auto_fallback.auto_fallback_node_factory import AutoFallbackNodeFactory
from taf.rfrl.csv4all.resources.node.feature.auto_fallback.auto_fallback_node import AutoFallbackNode
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, wrapper_decorator, function_wrapper
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger
from taf.rfrl.csv4all.resources.node.pdu_manager.pdu_manager import PduManager


class SwitchDict(TypedDict):
    switch_dict: str
    pdu_model: str
    pdu_version: str
    pdu_port: str


class AutoFallback(NetactFeatureTest):

    def __init__(self, nodes_details, test_nodes_details: List[dict], netact_dict: dict,
                 qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 sw_build: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 feature: Optional[str] = None, stop_test_after_fail: bool = False,
                 deintegrate_after_test: bool = True, config_type: str = None, artifactory_location: str = "espoo2",
                 package_suffix: str = "A54", synchronize_software_on_passive: bool = False,
                 fallback_timer: Optional[str] = None, switch_dict: Optional[SwitchDict] = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details=nodes_details, test_nodes_details=test_nodes_details, iterations_per_node=1,
                         netact_dict=netact_dict, report=False, calculate_kpi=False, qc_domain=qc_domain,
                         qc_id=qc_id, qc_project=qc_project, customers_list=customers_list,
                         sw_build=sw_build, use_external_storage=use_external_storage, download_path=download_path,
                         feature=feature, rollback=False, stop_test_after_fail=stop_test_after_fail,
                         deintegrate_after_test=deintegrate_after_test, config_type=config_type,
                         artifactory_location=artifactory_location, package_suffix=package_suffix,
                         synchronize_software_on_passive=synchronize_software_on_passive, fallback=True,
                         detailed_console_log=detailed_console_log, collect_passed_logs=collect_passed_logs)
        self.failed_nodes_during_auto_fallback = None
        self.node_factory = AutoFallbackNodeFactory()
        self.fallback_timer = int(fallback_timer) if isinstance(fallback_timer, str) and fallback_timer.isdigit()\
            else fallback_timer
        self.switch_details = switch_dict
        self.operation = "Auto_fallback_with_non-default_swFallbackTimer" if self.fallback_timer else "Auto-fallback"

    def test(self):
        self.run_iteration_precondition()
        self.precondition_before_autofallback()
        self.auto_fallback_test()
        self.verify_failed_nodes_after_iteration()

    def precondition_before_autofallback(self):
        with RobotWrapper("Auto-Fallback Precondition", "kw"):
            for node in self.test_nodes:
                if node.get_active_sw() == node.source_sw:
                    test_logger("Preparing node for auto-fallback")
                    node.reset_admin()
                    node.prepare_node_before_fallback()
                    node.netact_target_sw = self.get_target_sw(node.target_sw)
                    self.live_update_precheck(node)
                    node.add_test_specific_alarm("4085")
                    self.multi_runner.start_log_tracing_all_nodes()

    def run_test_operation(self):
        with RobotWrapper("Auto-Fallback test", "kw") as wrapper:
            for node in self.test_nodes:
                node: AutoFallbackNode
                node.update_sw_and_wait_for_reload()
                node.wait_for_sw_activation_reset(72000)

                self.failed_nodes[node.node_alias].update(self.auto_fallback_operation(node))

    @method_decorator()
    def auto_fallback_test(self):
        for node in self.test_nodes:
            node: AutoFallbackNode
            node.update_sw_and_wait_for_reload()
            node.wait_for_sw_activation_reset(72000)
            self.failed_nodes[node.node_alias].update(self.auto_fallback_operation(node))

    def auto_fallback_operation(self, node):
        try:
            self.perform_auto_fallback(node)
            node.restore_all_interfaces()
            node.verify_active_sw_version(node.source_sw)
            node.verify_node_after_fallback()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.failed_nodes_during_auto_fallback = self.multi_runner.verify_all_nodes(10, 0)
            test_logger(f"[{node.node_alias}] {self.operation} PASSED", hyperlink=True)
            self.multi_runner.stop_log_tracing_and_download_from_all_nodes(
                logs_dir=f"{self.current_logs_dir}/{self.operation}")
            if not self.failed_nodes_during_auto_fallback:
                self.check_connection_after_fallback_and_collect_snapshot(node)
        except Exception as e:
            self.failed_nodes_during_auto_fallback = {node.node_alias}
            node.restore_all_interfaces()
            self.exception_handling(self.operation, e)
            self.multi_runner.stop_log_tracing_and_download_from_all_nodes(logs_dir=f"{self.current_logs_dir}")
            if self.switch_details:
                self.perform_pdu_operation("power on")
            return self.failed_nodes_during_auto_fallback
        finally:
            node.logsverify.reset_check = False
            node.cleanup_after_fallback()
            if node.netboot_changed:
                node.change_netboot_state("on")
            if self.fallback_timer:
                node.set_sw_fallback_timer(0)
        return self.failed_nodes_during_auto_fallback

    @method_decorator()
    def check_connection_after_fallback_and_collect_snapshot(self, node):
        if self.check_connection_with_netact(node):
            raise
        if not self.passed_logs_gathered:
            self.gather_mumin_logs_and_snapshot(self.operation)
            self.send_snapshot_to_nescrotta(node, self.operation)

    def perform_auto_fallback(self, node):
        tx_disable = False if self.switch_details else True
        if self.fallback_timer and not node.fsm3:
            self.perform_auto_fallback_with_non_default_timer(node, tx_disable)
        else:
            if node.fsm3:
                self.perform_auto_fallback_for_fsm3(node, tx_disable)
            else:
                self.auto_fallback_with_cni(node, tx_disable)

    @method_decorator()
    def perform_pdu_operation(self, operation):
        with PduManager(
                pdu_ip=self.switch_details['pdu_ip'],
                pdu_model=self.switch_details["pdu_model"],
                pdu_version=self.switch_details["pdu_version"],
                device_alias=f"trs {operation}"
        ) as pdu:
            if operation == "power on":
                pdu.power_on(int(self.switch_details["pdu_port"]))
            elif operation == "power off":
                pdu.power_off(int(self.switch_details["pdu_port"]))

    @function_wrapper
    def perform_auto_fallback_with_non_default_timer(self, node, tx_disable):
        node: AutoFallbackNode
        if not tx_disable:
            self.perform_pdu_operation("power off")
        node.disconnect_trs_and_wait_for_reset(
            self.fallback_timer, "auto fallback", upper_threshold=0.3, tx_disable=tx_disable)
        if not tx_disable:
            self.perform_pdu_operation("power on")
        node.disconnect_trs_and_wait_for_reset(20, "reset after fallback", 0.99, 0.0, False)
        appear = node.disconnect_trs_and_wait_for_reset(20, "secondary reset after fallback", 0.99, 0.0, False)
        if not appear:
            test_logger(f"the secondary reset was not triggered after auto fallback")

    @function_wrapper
    def perform_auto_fallback_for_fsm3(self, node, tx_disable):
        node: AutoFallbackNode
        if not tx_disable:
            self.perform_pdu_operation("power off")
        node.disconnect_trs_and_wait_for_reset(90, "auto fallback", upper_threshold=0.3, tx_disable=tx_disable)
        if not tx_disable:
            self.perform_pdu_operation("power on")
        node.disconnect_trs_and_wait_for_reset(20, "reset after fallback", 0.99, 0.0, False)
        appear = node.disconnect_trs_and_wait_for_reset(20, "secondary reset after fallback", 0.99, 0.0, False)
        if not appear:
            test_logger(f"the secondary reset was not triggered after auto fallback")

    def auto_fallback_with_cni(self, node, tx_disable):
        node: AutoFallbackNode
        if not tx_disable:
            self.perform_pdu_operation("power off")
        self.disconnect_trs_and_wait_for_recovery_reset(node, tx_disable)
        self.disconnect_trs_and_wait_for_auto_fallback(node, tx_disable)
        self.disconnect_trs_and_wait_for_reset_after_auto_fallback(node, tx_disable)
        start = time.time()
        appear = self.disconnect_trs_and_wait_for_secondary_reset_after_fallback(node, tx_disable)
        if appear:
            self.disconnect_trs_and_wait_for_recovery_reset_after_fallback(
                node, reset_interval=40, upper_threshold=0.2, tx_disable=tx_disable)
        else:
            stop = time.time()
            test_logger(f"the secondary reset was not triggered after auto fallback")
            time_without_reset = stop - start
            reset_interval = 40 - (int(time_without_reset)//60)
            self.disconnect_trs_and_wait_for_recovery_reset_after_fallback(
                node, reset_interval=reset_interval, upper_threshold=0.4, tx_disable=tx_disable,
                time_without_reset=time_without_reset)
        if not tx_disable:
            self.perform_pdu_operation("power on")

    @staticmethod
    @function_wrapper
    def disconnect_trs_and_wait_for_recovery_reset(node, tx_disable):
        node.disconnect_trs_and_wait_for_reset(65, "recovery reset", upper_threshold=0.3, tx_disable=tx_disable)

    @staticmethod
    @function_wrapper
    def disconnect_trs_and_wait_for_auto_fallback(node, tx_disable):
        node.disconnect_trs_and_wait_for_reset(30, "auto fallback", upper_threshold=0.4, tx_disable=tx_disable)

    @staticmethod
    @function_wrapper
    def disconnect_trs_and_wait_for_reset_after_auto_fallback(node, tx_disable):
        node.disconnect_trs_and_wait_for_reset(10, "reset after fallback", 0.99, 0.2, tx_disable=tx_disable)

    @staticmethod
    @function_wrapper
    def disconnect_trs_and_wait_for_secondary_reset_after_fallback(node, tx_disable):
        return node.disconnect_trs_and_wait_for_reset(15, "secondary reset after fallback", 0.99, 0.05,
                                                      tx_disable=tx_disable)

    @staticmethod
    @function_wrapper
    def disconnect_trs_and_wait_for_recovery_reset_after_fallback(node, reset_interval, upper_threshold, tx_disable,
                                                                  time_without_reset):
        node.disconnect_trs_and_wait_for_reset(
            reset_interval=reset_interval, test_stage="recovery reset after auto fallback",
            upper_threshold=upper_threshold, tx_disable=tx_disable, time_without_reset=time_without_reset)

    @wrapper_decorator
    def _precondition(self, node):
        node: AutoFallbackNode
        self._set_current_logs_dir(node)
        active_sw = node.get_active_sw()
        if node.source_sw != active_sw:
            raise FatalError(f"Expected software on BTS is different than requested\n"
                             f"Current software: {active_sw}\n"
                             f"Expected software: {node.source_sw}")
        if self.fallback_timer:
            node.set_sw_fallback_timer(self.fallback_timer)
        if not self.switch_details:
            node.trs_sfp = node.find_trs_sfp()
        if self.uboot.uboot_scripts_prepared:
            self.perform_uboot_downgrade_if_needed(node)
